using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;
public static class FreshWorldPairR17 {
 [Serializable]class Throw {public string initialBody,finalState,impacts,breaks,resource;public int ticks,colliders,targets;public string actorMeshes;public bool finished;}
 [Serializable]class Receipt {public bool freshWorld,sceneSameOnRetry;public string error;public Throw[] throws;public int readyFragments,readyCityFragments,readyPeople,readyBirds,readyBreaks,readyOwned,readyCrabOwned,readyColliders;public double retryMs;public int cachedMeshes,cacheBuilds,cacheHits;public bool cacheReleased;}
 static RigidCrabFlight World(CrabFlightGame g)=>(RigidCrabFlight)typeof(CrabFlightGame).GetField("world",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(g);
 static string ActorMeshes(RigidCrabFlight w){var rows=new System.Collections.Generic.List<string>();foreach(var root in w.Scene.GetRootGameObjects())foreach(var rig in root.GetComponentsInChildren<CrabLifeActors.LifeActorRig>(true)){var m=rig.Renderer.sharedMesh;using(var stream=new MemoryStream()){using(var b=new BinaryWriter(stream,System.Text.Encoding.UTF8,true)){b.Write(m.vertexCount);foreach(var v in m.vertices){b.Write(v.x);b.Write(v.y);b.Write(v.z);}foreach(var v in m.normals){b.Write(v.x);b.Write(v.y);b.Write(v.z);}foreach(var v in m.colors){b.Write(v.r);b.Write(v.g);b.Write(v.b);b.Write(v.a);}foreach(var v in m.triangles)b.Write(v);foreach(var v in m.boneWeights){b.Write(v.boneIndex0);b.Write(v.boneIndex1);b.Write(v.boneIndex2);b.Write(v.boneIndex3);b.Write(v.weight0);b.Write(v.weight1);b.Write(v.weight2);b.Write(v.weight3);}foreach(var v in m.bindposes)for(int i=0;i<16;i++)b.Write(v[i]);var z=m.bounds;b.Write(z.center.x);b.Write(z.center.y);b.Write(z.center.z);b.Write(z.size.x);b.Write(z.size.y);b.Write(z.size.z);}using(var sha=System.Security.Cryptography.SHA256.Create())rows.Add(root.name+"/"+rig.Kind+"/"+BitConverter.ToString(sha.ComputeHash(stream.ToArray())).Replace("-", ""));}}rows.Sort(StringComparer.Ordinal);return string.Join("\n",rows);}
 public static void Before(){Execute(true,"native-before01");}
 public static void After(){Execute(true,"native-after01");}
 static void Execute(bool fresh,string name){var dir=Path.GetFullPath("../../../../finish-r17-evidence/"+name);Directory.CreateDirectory(dir);var r=new Receipt{freshWorld=fresh,throws=new Throw[2]};CrabFlightGame game=null;try{UnityEngine.Random.InitState(42043);game=BuildFlight.PrepareScene();game.Initialize();game.enabled=false;game.LoadFeelR27(File.ReadAllText("Assets/StreamingAssets/feel.json"));var input=File.ReadAllText("../../../../accepted-input.json");for(int turn=0;turn<2;turn++){UnityEngine.Random.InitState(42043);game.ReviewReplayAcceptedCalmR3(input);var w=World(game);var t=new Throw{initialBody=game.State().launchReceipt.bodyJson,actorMeshes=ActorMeshes(w),colliders=w.ColliderCount,targets=w.CityContactTargets};r.throws[turn]=t;for(int k=0;k<18000&&!game.Finished;k++){game.Tick(1f/60);t.ticks++;}t.finished=game.Finished;t.finalState=JsonUtility.ToJson(game.State());t.impacts=string.Join("\n",w.Impacts.Select(x=>JsonUtility.ToJson(x)));t.breaks=string.Join("\n",w.BreakEvents.Select(x=>JsonUtility.ToJson(x)));t.resource=string.Join("\n",w.OverdriveImpulses.Select(x=>JsonUtility.ToJson(x)));if(!t.finished||game.State().physicsFault.Length>0)throw new Exception("Flight failed");if(turn==0){var scene=w.Scene;var start=System.Diagnostics.Stopwatch.StartNew();game.Prepare("");start.Stop();w=World(game);r.retryMs=start.Elapsed.TotalMilliseconds;r.sceneSameOnRetry=scene==w.Scene;r.readyFragments=w.ActiveFragments;r.readyCityFragments=w.CityFragments;r.readyPeople=w.PeopleHitR6;r.readyBirds=w.BirdsHitR6;r.readyBreaks=w.DestructionEvent;r.readyColliders=w.ColliderCount;if(r.sceneSameOnRetry)throw new Exception("Original new-scene initialization was not preserved");if(r.readyFragments!=0||r.readyCityFragments!=0||r.readyPeople!=0||r.readyBirds!=0||r.readyBreaks!=0||r.readyColliders!=13)throw new Exception("Retry state/resource mismatch");}}}catch(Exception ex){r.error=ex.ToString();throw;}finally{if(game){var field=typeof(CrabFlightGame).GetField("lifeGeometryCacheR17",BindingFlags.Instance|BindingFlags.NonPublic);var cache=field!=null?field.GetValue(game)as CrabLifeActors.LifeGeometryCacheR17:null;if(cache!=null){r.cachedMeshes=cache.Count;r.cacheBuilds=cache.Builds;r.cacheHits=cache.Hits;}game.ShutdownReviewPhysics();r.cacheReleased=cache==null||cache.Count==0;}File.WriteAllText(dir+"/receipt.json",JsonUtility.ToJson(r,true));}}
}
